TDP.CollectionAcquisitionGuides = {
    mounts = {
        [127178] = "Buy Jungle Riding Crane from Hemet Nesingwary XVII in Shrine of Two Moons (26.0, 49.0) for 2,200 Bronze.\n\nMists of Pandaria Remix reward: this acquisition required a Timerunner during the event, which has ended.\n\nPandaria Remix has ended. This event-specific mount has no current acquisition source.",
        [254812] = "Original Plunderstorm acquisition: play the Plunderstorm event from the character-selection screen, collect Plunder through matches and its daily quest, then buy Royal Seafeather for 5,000 Plunder in the Plunderstore.\n\nThe first event also awarded it at Renown 20 with Keg Leg's Crew.\n\nThis recorded event has ended. The item is an event reward, with no ordinary world drop or permanent gold vendor; another opportunity depends on its inclusion in a returning Plunderstorm event.\n\nRequires Renown 20 with Keg Leg's Crew.",
        [300154] = "Original Plunderstorm acquisition: play the Plunderstorm event from the character-selection screen, collect Plunder through matches and its daily quest, then buy Silver Tidestallion for 1,500 Plunder in the Plunderstore.\n\nThe first event also awarded it at Renown 10 with Keg Leg's Crew.\n\nThis recorded event has ended. The item is an event reward, with no ordinary world drop or permanent gold vendor; another opportunity depends on its inclusion in a returning Plunderstorm event.\n\nRequires Renown 10 with Keg Leg's Crew.",
        [303767] = "Earn I'm On Island Time: 40 Points Account-wide progress Aid Zandalar and Kul Tiras by completing the achievements below. - Hot Tropic - Bwon Voyage - Dune Squad - Loremaster of Zandalar - Battle for Azeroth Explorer - Sound Off - Songs of Storms - When the Drust Settles - Loremaster of Kul Tiras - Wide World of Quests",
        [332482] = "This mount has no confirmed obtainable version. The advertised Shadowlands Timewalking purchase did not appear on Collector Ta'steld, and Sabriel the Bonecleaver's beta drop was never released. Do not farm Sabriel or spend Timewarped Badges expecting this mount; his live mount reward is Armored Bonehoof Tauralus. Keep this entry as an unreleased collectible until an actual acquisition source is confirmed.",
        [351408] = "Earn Centaur of Attention: 20 Points Account-wide progress Aid the Maruuk Centaur by completing the achievements below. - Hunt Master - The Best at What I Do - Tetrachromancer - Adventurer of the Ohn'ahran Plains - Longhunter - The Disgruntled Hunter - Who's a Good Bakar? - Treasures of the Ohn'ahran Plains",
        [353264] = "Reach Renown 8 with the Manaforge Vandals. Obtain the Inscription items Deal: Cartel Ba, Deal: Cartel Zo and Deal: Cartel Om, by crafting them or buying them on the Auction House. Use one deal per account each week and equip its cartel title. While aligned, collect that cartel's hidden cypher inside Manaforge Omega: Ba is after Plexus Sentinel near the phase-warp ledge; Zo is on the mana-vent pipes before Forgeweaver Araz; Om is on a rock in the area opened after Fractillus. Leave Araz alive while collecting Ba and Zo. After all three cyphers, return to Zo'turu in K'aresh (42.0, 22.1) and finish Someone Like Me for the mount and Cartel Transmorpher. Allow three weekly cartel selections.",
        [353265] = "Complete Welcome to the Team from Zo'turu in K'aresh (42.0, 22.1) to receive Vandal's Gearglider.\n\nMy friend, we have made much progress together in bringing down the Shadowguard. For your sacrifices and efforts, my colleagues and I consider you one of us. Please, take this modified Gearglider as a show of our gratitiude - may it carry you safely to your next mission.\n\nRequires Renown 8 with Manaforge Vandals.",
        [368893] = "Follow the Embers of Neltharion campaign into Zaralek Cavern and complete chapter 4, Inherited Sin. Ebyssian's final quest, Worst of the Worst, at Slitherdrake Roost (53.6, 30.2), rewards the Winding Slitherdrake after you defeat Overseer Xymra. Continue the campaign prerequisites shown in the quest-chain notes if this quest is not available yet.",
        [371176] = "Buy Subterranean Magmammoth from Saccratros in Zaralek Cavern (55.9, 55.4) for 100 Coveted Bauble.",
        [373967] = "Earn Across the Isles: 40 Points Account-wide progress Aid the Dragon Isles by completing the achievements below. - Wake Me Up - Army of the Fed - Closing Time - Nothing Stops the Research - Dream Shaper - Centaur of Attention - Flight Club - Into the Storm - Through the Ashes and Flames",
        [374071] = "Earn Closing Time: 20 Points Account-wide progress Aid the Timewalkers by completing the achievements below. - The Future We Make - Chronograde Connoisseur - Minute Menagerie - Lock and Load - Dawn of the Infinite: Galakrond's Fall - Verified Rifter - Just Following Chronological Orders - Collapsed Reality - To All The Squirrels I've BEEN Before - Dawn of the Infinite: Murozond's Rise",
        [374097] = "Earn Into the Storm: 20 Points Account-wide progress Complete the storm achievements below. - Storm Chaser - Elemental Overload - Stormed Off - Storming the Runway",
        [374138] = "Loot Seething Cache in Zaralek Cavern (32.3, 39.4) to obtain Seething Slug.\n\nYou'll need to pick up 3x stacks of a Insidious Insight debuff from Seething Orbs located in the Zaqali Caldera . Warning: While you may click each Seething Orb with multiple players, when the first player clicks the Seething Cache, the debuff will be removed from all nearby players and the cache itself will be gone!",
        [374172] = "Earn Army of the Fed: 20 Points Account-wide progress Aid the Iskaara Tuskarr by completing the achievements below. - Soupervisor - Secret Fishing Spots - We're Going to Need a Bigger Harpoon - Adventurer of The Azure Span - Leftovers' Revenge - Taking From Nature - Lend a Helping Span - Treasures of The Azure Span",
        [374204] = "Buy Explorer's Stonehide Packbeast from Provisioner Aristta in Thaldraszus (61.4, 31.4) for 20,000 Mysterious Fragment.",
        [374278] = "Wait for an active Dreamsurge in one of the four original Dragon Isles zones. Join its Waking Dream portals and defeat the empowered flame lieutenants for Charred Elemental Remains. Collect 20 remains on one character, then combine them to create the Renewed Magmammoth. This is a combination reward, rather than a vendor purchase or a single guaranteed boss drop.",
        [376898] = "Earn Flight Club: 20 Points Account-wide progress Aid the Valdrakken Accord by completing the achievements below. - Siege on Dragonbane Keep: Home Sweet Home - Siege on Dragonbane Keep: Chiseled Record - Obsidian Keymaster - Whelp, There It Is - Hey Nanny Nanny - Treasures of Thaldraszus - Siege on Dragonbane Keep: Snack Attack - I'm Playing All Sides - Obsidian Champion - Daycare Derby - Adventurer of Thaldraszus",
        [385260] = "Earn Wake Me Up: 20 Points Account-wide progress Aid the Dragonscale Expedition and the Waking Shores by completing the achievements below. - A Legendary Album - Lead Climber - Dragonscale Expedition: The Highest Peaks - Adventurer of The Waking Shores - Great Shots Galore! - How Did These Get Here? - Well Supplied - Treasures of The Waking Shores",
        [385262] = "Buy Duskwing Ohuna from Celestine of the Harvest in The Waking Shores (58.4, 67.8) for 1,000 Dreamsurge Coalescence.",
        [406637] = "Buy Inferno Armoredon from Lindormi in Silvermoon City (42.1, 58.8) for 1 Timelost Saddle.",
        [407555] = "You must own Dragonwrath, Tarecgosa's Rest and complete Kalecgos's blue dragonflight story in Dragonflight, ending with A New Dawn. With the legendary staff available, speak to Kalecgos at the Veiled Ossuary in Thaldraszus (65.7, 12.6) for Rhapsody in Blue. Prepare Tarecgosa's grave and complete the ritual to learn her visage as a permanent mount. This does not consume the staff.",
        [408313] = "Complete Snailed It from Briggul in Zaralek Cavern (44.2, 80.0) to receive Big Slick in the City.\n\nIntroduce yourself to Slick.\n\nRequires Renown 7 with Loamm Niffen.\n\nReach rank 5 with Glimerogg Racer by completing daily snail training quests for Briggul in Glimmerogg.",
        [408627] = "Buy Igneous Shalewing from Saccratros in Zaralek Cavern (55.9, 55.4) for 400 Coveted Bauble.",
        [408647] = "Defeat Karokta in Zaralek Cavern (42.2, 65.9) and loot Cobalt Shalewing. This is a chance drop.",
        [408648] = "Earn Que Zara(lek), Zara(lek): 25 Points Account-wide progress Complete all of the Zaralek Cavern achievements listed below. - Embers of Neltharion - The Smell of Money - There's No Place Like Loamm - Sniffen Around - Adventurer of Zaralek Cavern - Explore Zaralek Cavern - Treasures of Zaralek Cavern",
        [408649] = "Earn Glory of the Aberrus Raider: 25 Points Account-wide progress Complete the Aberrus, the Shadowed Crucible raid achievements listed below. - Cosplate - Tabula Rasa - Whac-A-Swog - Escar-Go-Go-Go - We'll Never See That Again, Surely - I'll Make My Own Shadowflame - Are You Even Trying? - Eggscellent Eggsecution - Objects in Transit May Shatter",
        [408651] = "Join Researchers Under Fire at the central platform in Zaralek Cavern (47.5, 56.7), when the event is active. Help the researchers finish the objectives and open your weekly researcher reward bag. Cataloged Shalewing is a chance reward from the researcher bags, so finishing the event does not guarantee the mount. Complete as many objectives as possible for the better reward tier.",
        [408653] = "Reach Renown 3 with the Loamm Niffen to unlock bartering, then earn Barter Bricks through Zaralek Cavern activities and Ponzo's barter quests. Buy the Boulder Hauler from Ponzo in Loamm (58.1, 53.8). His offers include 170 Barter Bricks or 85 Barter Boulders; the boulder currency becomes available as your Niffen bartering unlocks advance.",
        [408654] = "Buy Sandy Shalewing from Cupri in Shattrath City - 54.4, 38.8 for 5,000 Timewarped Badge.",
        [408655] = "Buy Morsel Sniffer from Harlowe Marl in Zaralek Cavern (56.5, 55.6) for 800 Dragon Isles Supplies.\n\nRequires Renown 18 with Loamm Niffen.",
        [408977] = "Earn Gladiator: Dragonflight Season 2: Win 50 3v3 games while at Elite rank during Dragonflight Season 2. - Win 50 Games as a Gladiator in Dragonflight Season 2 in 3v3\n\nThe original rated Arena season has ended. Its Gladiator mount cannot be earned in a later season.",
        [409032] = "Buy Vicious War Snail from Deathguard Netharian in Orgrimmar (41.8, 73.0) for 1 Vicious Saddle.",
        [409034] = "Buy Vicious War Snail from Necrolord Sipe in Stormwind City (76.8, 65.6) for 1 Vicious Saddle.",
        [413825] = "Complete Time to Fly to receive Scarlet Pterrordax.\n\nFind Beast Master Kalatak.\n\nReaching Level 30 will make this quest pop up.",
        [413827] = "Complete Time to Fly in Boralus to receive Harbor Gryphon.\n\nFind Leila Stafford.\n\nReaching Level 30 will make this quest pop up.",
        [413922] = "Unlock old Scholomance and the Wards of the Dread Citadel route into the restored Naxxramas content. Obtain a Rotten Delicious apple from Zackett Skullsmash in Naxxramas. Enter 10-player Naxxramas and leave Instructor Razuvious alive. Approach Valiance slowly and feed him the apple. Use an Obedience Crystal to control a Death Knight Understudy, bring the Understudy to Valiance so it mounts him, then ride back to Razuvious. Release the Understudy and kill Razuvious to loot Valiance's reins. The mount comes from this interaction, not from killing Valiance.",
        [414316] = "Buy White War Wolf from Warden Krizzik in Thaldraszus (51.1, 56.6) for 3,000 Paracausal Flakes.",
        [414323] = "Buy Ravenous Black Gryphon from Warden Krizzik in Thaldraszus (51.1, 56.6) for 3,000 Paracausal Flakes.",
        [414324] = "Buy Gold-Toed Albatross from Sorotis in Thaldraszus (51.1, 56.7) for 3,000 Paracausal Flakes.",
        [414326] = "Buy Felstorm Dragon from Falara Nightsong in Thaldraszus (51.0, 56.7) for 3,000 Paracausal Flakes.",
        [414327] = "Buy Sulfur Hound from Provisioner Qorra in Thaldraszus (51.1, 56.6) for 3,000 Paracausal Flakes.",
        [414328] = "Buy Perfected Juggernaut from Gill the Drill in Thaldraszus (51.0, 56.6) for 3,000 Paracausal Flakes.",
        [414334] = "Buy Scourgebound Vanquisher from Baron Sliver in Thaldraszus (51.0, 56.7) for 3,000 Paracausal Flakes.",
        [418078] = "Complete all 15 Secrets of Azeroth clues for Whodunnit?. Start with Preservationist Kathos in the Roasted Ram inn in Valdrakken (48.4, 47.8), beginning Preserving Rarities. Follow Kathos's and Tithris's clue quests in order: recover the thinking cap, Torch of Pyrreth and Idol of Ohn'ahra, then use those tools to solve the remaining clues and expose the thief. The chain remains available after the original event. Completing Under Suspicion finishes the achievement and awards Pattie.",
        [422486] = "Buy Verdant Armoredon from Lindormi in Silvermoon City (42.1, 58.8) for 1 Timelost Saddle.",
        [423871] = "Buy Blossoming Dreamstag from Sylvia Whisperbloom in Emerald Dream (59.8, 16.9) for 1 Seedbloom.",
        [423873] = "Buy Suntouched Dreamstag from Moon Priestess Lasara in Emerald Dream (50.3, 61.6) for 1,200 Dragon Isles Supplies.\n\nRequires Renown 17 with Dream Wardens.",
        [423877] = "Buy Rekindled Dreamstag from Sylvia Whisperbloom in Emerald Dream (59.8, 16.9) for 1 Seedbloom.",
        [423891] = "Buy Lunar Dreamstag from Moon Priestess Lasara in Emerald Dream (50.3, 61.6) for 1,200 Dragon Isles Supplies.\n\nRequires Renown 17 with Dream Wardens.",
        [424082] = "Collect three booster parts on the same character. First, bring three players with the Torch of Pyrreth to the braziers on Jaguero Isle, Cape of Stranglethorn (59.4, 79.0), summon Enigma Ward and loot its part. Second, loot the part in Irontree Woods, Felwood (49.9, 26.4). Third, go to the Dark Portal in the Blasted Lands (54.8, 52.1), destroy the nearby Legion Flak Cannons and channel on the part without being interrupted; use Zidormi's older phase if needed. Bring all three parts to the Empowered Arcane Forge in Valdrakken (36.5, 61.9) and combine them into Mimiron's Jumpjets. Obtain the Torch through the Secrets of Azeroth clues at the Roasted Ram inn if you do not have it.",
        [424474] = "Earn Glory of the Dream Raider: 25 Points Account-wide progress Complete the Amirdrassil, the Dream's Hope raid achievements listed below. - Meaner Pastures - Swog Champion - Don't Let the Doe Hit You On The Way Out - Haven't We Done This Before? - Memories of Teldrassil - Cruelty Free - Ducks In A Row - A Dream Within a Dream - Whelp, I'm Lost",
        [424476] = "Plant a Small Dreamseed at an Emerald Bounty soil patch in the Emerald Dream. Contribute Emerald Dewdrops while the seed grows, wait for the bloom to finish, then loot its Dreamseed Cache. Winter Night Dreamsaber is a rare reward from these caches. Gather more Dreamseeds and Dewdrops from Dream activities and repeat at other bounty patches; an individual planting does not guarantee a mount.",
        [424479] = "Buy Evening Sun Dreamsaber from Sylvia Whisperbloom in Emerald Dream (59.8, 16.9) for 1 Seedbloom.",
        [424482] = "Buy Morning Flourish Dreamsaber from Sylvia Whisperbloom in Emerald Dream (59.8, 16.9) for 1 Seedbloom.",
        [424484] = "Defeat Fyrakk on Mythic difficulty in Emerald Dream (27.3, 30.9) and loot Anu'relos, Flame's Guidance. This is a chance drop.",
        [424534] = "Buy Vicious Moonbeast from Necrolord Sipe in Stormwind City (76.8, 65.6) for 1 Vicious Saddle.",
        [424535] = "Buy Vicious Moonbeast from Deathguard Netharian in Orgrimmar (41.8, 73.0) for 1 Vicious Saddle.",
        [424539] = "Earn Gladiator: Dragonflight Season 4: Win 50 3v3 games while at Elite rank during Dragonflight Season 4. - Win 50 Games as a Gladiator in Dragonflight Season 4 in 3v3\n\nThe original rated Arena season has ended. Its Gladiator mount cannot be earned in a later season.",
        [424607] = "Earn A World Awoken: 100 Points Account-wide progress Usher in the second Age of Dragons by completing the following achievements. - Vault of the Incarnates - Amirdrassil, the Dream's Hope - Loremaster of the Dragon Isles - Dragon Quests - Dragon Isles Pathfinder - You Know How to Reach Me - Dream On - Aberrus, the Shadowed Crucible - Myths of the Dragonflight Dungeons - Friend of the Dragon Isles - Oh My God, They Were Clutchmates - Across the Isles - Que Zara(lek), Zara(lek) - Now THIS is Dragon Racing!",
        [425338] = "Complete Emerald Welcome from Merithra in Ohn'ahran Plains (18.7, 51.8) to receive Flourishing Whimsydrake.\n\nObjectives: - Cross into the Emerald Dream - Speak to Merithra",
        [425416] = "Earn Gladiator: Dragonflight Season 3: Win 50 3v3 games while at Elite rank during Dragonflight Season 3. - Win 50 Games as a Gladiator in Dragonflight Season 3 in 3v3\n\nThe original rated Arena season has ended. Its Gladiator mount cannot be earned in a later season.",
        [426955] = "Buy Springtide Dreamtalon from Sylvia Whisperbloom in Emerald Dream (59.8, 16.9) for 1 Seedbloom.",
        [427041] = "Complete A Little Hope is Never Without Worth from Professor Ash in Emerald Dream (48.7, 68.0) to receive Ochre Dreamtalon.\n\nSpeak to Professor Ash.",
        [427043] = "Buy Snowfluff Dreamtalon from Sylvia Whisperbloom in Emerald Dream (59.8, 16.9) for 1 Seedbloom.",
        [427222] = "Buy Delugen from Elianna in Emerald Dream (50.2, 61.8) for 1 Dream Infusion.\n\nRequires Renown 5 with Dream Wardens.",
        [427224] = "Buy Talont from Elianna in Emerald Dream (50.2, 61.8) for 1 Dream Infusion.\n\nRequires Renown 5 with Dream Wardens.",
        [427226] = "Buy Stargrazer from Elianna in Emerald Dream (50.2, 61.8) for 1 Dream Infusion.\n\nRequires Renown 5 with Dream Wardens.",
        [427546] = "Buy Mammyth from Elianna in Emerald Dream (50.2, 61.8) for 1 Dream Infusion.\n\nRequires Renown 5 with Dream Wardens.",
        [427549] = "Buy Imagiwing from Elianna in Emerald Dream (50.2, 61.8) for 1 Dream Infusion.\n\nRequires Renown 5 with Dream Wardens.",
        [427724] = "Buy Salatrancer from Elianna in Emerald Dream (50.2, 61.8) for 1 Dream Infusion.\n\nRequires Renown 5 with Dream Wardens.",
        [428013] = "Unlock the Detective title through Azeroth's Greatest Detective and obtain the Torch of Pyrreth from Secrets of Azeroth. Equip Detective and begin Ratts' Race with the Dalaran Survivor in Dornogal (54.9, 28.9). Read the notes in Azj-Kahet (69.3, 93.3), above the City of Threads (31.5, 20.8), and underwater in Hallowfall (50.7, 86.6). Confront Ratts in the hidden upper tunnel inside Pillar-nest Vosh, Azj-Kahet (entrance 55.1, 19.0; climb at 56.4, 17.5), and take the Peculiar Gem. Use the torch in the rotten tree trunk in northern Un'Goro (44.5, 8.0) for the Inert Peculiar Key. Combine them, carry the resulting key to the Karazhan Catacombs gate in Deadwind Pass (46.3, 69.1), and use the torch to enter Ratts' Revenge. Solve the following nine basins in order. You do not need the later flight-unlock puzzles to obtain the mount.\n\n1. With your torch active, wait for The Light of Their Love at the Humble Monument in Northern Barrens (55.0, 40.2), Young Olgra in Draenor Nagrand (74.2, 37.5 or 49.2, 48.0 depending on your story phase), and Decimator Olgra in Maldraxxus (27.3, 61.3). Obtain all three stacks.\n\n2. At the Ny'alotha Obelisk above the Seat of Knowledge in the BFA phase of Vale of Eternal Blossoms (83.7, 27.6), summon Perky Pug wearing a Dogg-Saron or Yipp-Saron costume, use Twitching Eyeball or All-Seeing Eyes for Gift of N'Zoth, and /pray. Wait nearby for the Key of Shadows. Another player can fulfill these requirements for everyone standing within ten yards.\n\n3. Back in the catacombs, open the chamber beside the Red Button with the key. Fish an Astral Key from the bowl, open the Astral Chest and equip Starry-Eyed Goggles. Use the consoles and loot their Pieces of Hate. Catacombs coordinates and codes: (48.9, 80.3) 88224646; (42.9, 70.6) 17112317; (49.5, 65.1) try 1533, 3457, 8265 or 10638; (67.4, 84.3) 19019; (56.3, 62.6) 5661; (64.9, 48.3) 52233; (70.3, 55.4) 51567; (66.3, 15.2) 115. For the ninth piece, carry at least five distinct lucky items, for example Lucky Rat's Tooth, Lucky Shirt, Lucky Horseshoe, Lucky Duck and Lucky Dragon's Claw, then enter 777 at a slot-machine console in the felcycle room. Keep all nine pieces.\n\n4. Buy a Scroll of Fel Binding from Vashti the Wandering Merchant in Azsuna. Use it outside Uther's Tomb in Western Plaguelands (52.1, 85.1), return after dying, and read all four writings while the summoned doomguard is alive.\n\n5. On Timeless Isle, ask Zarhym in the Cavern of Lost Spirits to enter the spirit realm. Reach Jeremy Feasel before the spirit timer expires. Defeat him with three level-25 secret pets, such as Baa'l, Wicker Pup and Sun Darter Hatchling; a grouped player's successful battle can also qualify you. Accept Jeremy's quest and obtain the Relic of Crystal Connections.\n\n6. Use your torch at the five acquisition altars in northeastern Northern Stranglethorn. One player must satisfy each altar's complete combination; friends can help with different altars. Blood (77.1, 46.3): a mount and pet with Blood in their names, plus Throbbing Blood Orb. Corruption (77.5, 43.9): Cloak of Overwhelming Corruption appearance, a Corrupted mount and pet, Ring of Broken Promises or Accursed Tome of the Sargerei, and /cower. Void (78.1, 46.3): Cloak of the Black Void appearance, Lesser Voidcaller or another qualifying void pet, Shadowy Disguise or Void Totem, and /smirk. Sin (78.3, 44.0): a sinstone back appearance, Sinheart, and Bondable Sinstone. Lust (77.1, 44.9): remove your clothes, summon Sister of Temptation, use Moroes' Famous Polish or Steamy Romance Novel Kit, and /flirt. With goggles equipped, loot Ancient Shaman Blood from the chest by the altars (78.2, 47.7).\n\n7. Summon Fledgling Warden Owl on Azsuna's Isle of the Watchers. Find the active owl statues and stand with your owl in each of the red, green, blue and purple auras until each triggers the magnifying-glass effect. Search the island around (40.5, 74.0), (43.5, 86.0), (47.5, 84.7) and (50.4, 91.7); the active statues rotate. Keep the empowered owl summoned and clear Vault of the Wardens. Take Elune's Light from Cordana's arena, return to the newly opened room before the first boss and collect the Sentry Statue. Place it in the Vault of Mirrors. Lower every statue in its five-by-five toggle puzzle to loot Warden's Mirror.\n\n8. Insert Ancient Shaman Blood and Warden's Mirror into the Enigma Machine at catacombs (59.9, 42.6). Begin, then submit to release Rats. Count and kill every Rat, excluding creatures named Catacombs Rat; kill those as well so they cannot stand on plates. Complete three locks. For each lock multiply the Rat count by the lock number; subtract 20 if the result exceeds 20. Count that result along the seven plates repeatedly: 1-7 means one statue on plate 1-7, 8-14 means two statues on plate 1-7, and 15-20 means three statues on plate 1-6. Submit the arrangement, clear the plate and repeat for the next lock. Plate coordinates, in order: (71.6, 20.1), (68.5, 34.2), (73.6, 43.0), (68.8, 50.9), (73.6, 65.3), (60.2, 71.6), (47.8, 78.9). Reach plate 3 by targeting its Humming Crystal and using the relic. A wrong submission requires clearing the Rats and restarting.\n\n9. Return to the hidden upper tunnel in Pillar-nest Vosh. Wear the goggles to reveal the platform and use the relic on its Humming Crystal. Submit 84847078 at the console, then open the Encrypted Chest to learn Incognitro.",
        [428060] = "Visit Madam Goya's Black Market Auction House in Valdrakken, below the Little Scales Daycare (34.6, 60.6), or another Black Market broker. When the Golden Regal Scarab is listed, place the winning gold bid before the auction expires, then collect it from your mail. Inventory rotates and other players can outbid you; this mount has no fixed buyout or guaranteed listing day.",
        [428068] = "Enter the revisited Horrific Vision of Stormwind with at least one Faceless Mask active. Defeat Haymar the Devout in the Dwarven District and send his bike frame to Dornogal. Rebuild it at Dornogal (33.6, 68.0). Collect the manifold near Stormwind's Trade District auction house, handlebars from Valeera's chest, crystal from Umbric's chest, and wheel materials from Wyrmbane's chest. In the Orgrimmar rotation, collect the engine block in the Drag, boarhide from Rexxar's chest and wheel materials from Geya'rah's chest. Each part needs an active mask. Combine them with the crafting reagents shown by the frame, then install the repaired engine, exhaust, handlebars, battery, seat and two wheels. Stormwind and Orgrimmar alternate, so plan for both rotations.",
        [430225] = "Complete Beginning a New Dawn from Genn Greymane in Ruins of Gilneas City (58.7, 47.8) to receive Gilnean Prowler.\n\nListen to Genn Greymane's conversation with Tess.",
        [431049] = "Complete the Wrathion and Vyranoth side story that opens during Guardians of the Dream. Pick up The Dragon Isles Await from Wrathion at the Central Encampment in the Emerald Dream, follow the Netherwing and storm-dragon errands, and finish Dragon Keeping to receive the Grotto Netherwing Drake. The July 2023 Trading Post reward was its original source; the quest chain provides a permanent way to obtain the mount.",
        [432610] = "Defeat Doomshadow in The Azure Span (27.8, 46.2) and loot Clayscale Hornstrider. This is a chance drop.",
