        [1261668] = "Buy Bronze Wilderling from Cupri in Shattrath City - 54.4, 38.8 for 5,000 Timewarped Badge.",
        [1261671] = "Buy Bronze Aquilon from Cupri in Shattrath City - 54.4, 38.8 for 5,000 Timewarped Badge.",
        [1261677] = "Buy Bronze Corpsefly from Cupri in Shattrath City - 54.4, 38.8 for 5,000 Timewarped Badge.",
        [1261681] = "Buy Bronze Gravewing from Cupri in Shattrath City - 54.4, 38.8 for 5,000 Timewarped Badge.",
        [1262886] = "Earn Worldsoul-Searching: 100 Points Account-wide progress Chase down the mysteries within (and without) Azeroth by completing the following achievements. - Nerub-ar Palace - Manaforge Omega - You Xal Not Pass - Glory of the War Within Delver - Owner of a Radiant Heart - Liberation of Undermine - All That Khaz - The War Within Pathfinder - Going Goblin Mode - Unraveled and Persevering",
        [1263369] = "During Shadowlands Timewalking, visit Collector Ta'steld in the Ring of Fates in Oribos and buy Skypaw Glimmerfur for 5,000 Timewarped Badges. Earn the badges from Timewalking dungeons, raids and their event quests. The vendor follows the active Timewalking schedule, so return during the Shadowlands event if the item is absent.",
        [1263387] = "Buy Crimson Lupine from Collector Ta'steld in Oribos (56.3, 63.7) for 5,000 Timewarped Badge.",
        [1264621] = "Join the Brawler's Guild in your faction's arena: Bizmo's Brawlpub beneath the Deeprun Tram in Stormwind, or Brawl'gar Arena in Orgrimmar. Win the ranked solo encounters until rank 6, then buy Brawlin' Bruno from the arena quartermaster for 4,000 gold. Each rank requires defeating its encounter sequence; random exhibition fights do not substitute for rank progression. The purchase is available during an active Brawler's Guild season.",
        [1264643] = "Progress through the ranked Brawler's Guild encounters in Bizmo's Brawlpub beneath Stormwind's Deeprun Tram or Brawl'gar Arena in Orgrimmar. Reach rank 8, then buy Ballistic Bronco from the arena quartermaster for 10,000 gold. Work through the rank bosses in order; exhibition fights do not advance the required rank. This route requires an active Brawler's Guild season.",
        [1264988] = "Buy Snowpaw Glimmerfur Prowler from Collector Ta'steld in Oribos (56.3, 63.7) for 5,000 Timewarped Badge.",
    },
