        [4411] = "Earn Just One More Thing: 10 Points Account-wide progress Complete any site's entry in the Tome of Archived Isles Research for Nirobin of the Azerothian Archives. - Lost Atheneum - Igira's Watch - Concord Observatory - The Riverbed - Gaze of Neltharion - Winglord's Perch\n\nEach related Research World Quest needs to be completed 3 times to get credit for one criteria.",
        [4412] = "Earn Finally At Rest: 10 Points Account-wide progress Acquire The Story of Traitor's Rest entries for Eadweard Dalyngrigge and the Azerothian Archives while participating in The Big Dig. - The Big Dig: Traitor's Rest",
        [4425] = "Original Plunderstorm acquisition: play the Plunderstorm event from the character-selection screen, collect Plunder through matches and its daily quest, then buy Glamrok for 1,000 Plunder in the Plunderstore.\n\nThe first event also awarded it at Renown 30 with Keg Leg's Crew.\n\nThis recorded event has ended. The item is an event reward, with no ordinary world drop or permanent gold vendor; another opportunity depends on its inclusion in a returning Plunderstorm event.\n\nRequires Renown 30 with Keg Leg's Crew.",
        [4426] = "Original Plunderstorm acquisition: play the Plunderstorm event from the character-selection screen, collect Plunder through matches and its daily quest, then buy Bubbles for 500 Plunder in the Plunderstore.\n\nThe first event also awarded it at Renown 11 with Keg Leg's Crew.\n\nThis recorded event has ended. The item is an event reward, with no ordinary world drop or permanent gold vendor; another opportunity depends on its inclusion in a returning Plunderstorm event.\n\nRequires Renown 11 with Keg Leg's Crew.",
        [4435] = "Original Plunderstorm acquisition: play the Plunderstorm event from the character-selection screen, collect Plunder through matches and its daily quest, then buy Happy for 250 Plunder in the Plunderstore.\n\nThe first event also awarded it at Renown 6 with Keg Leg's Crew.\n\nThis recorded event has ended. The item is an event reward, with no ordinary world drop or permanent gold vendor; another opportunity depends on its inclusion in a returning Plunderstorm event.\n\nRequires Renown 6 with Keg Leg's Crew.",
        [4450] = "These are the former Radiant Echoes vendor areas. The pre-expansion event and its Residual Memories vendors have ended; existing caged pets can still be traded or listed by players.",
        [4451] = "These are the former Radiant Echoes vendor areas. The pre-expansion event and its Residual Memories vendors have ended; existing caged pets can still be traded or listed by players.",
        [4452] = "These are the former Radiant Echoes vendor areas. The pre-expansion event and its Residual Memories vendors have ended; existing caged pets can still be traded or listed by players.",
        [4455] = "Buy Rak-Ush Threadling from Ves'trak in Azj-Kahet (74.7, 81.2) for 2,250 Kej.",
        [4456] = "Start wild pet battles in The Ringing Deeps (57.8, 42.6) and look for Arachnoid Hatchling in the opposing team's secondary slots. Reduce its health below 35%, trap it, and win the battle.\n\nFound commonly in groups around the Ringing Deeps and as backline in all 3 main underground zones.",
        [4457] = "Find a wild Chitin Burrower in The Ringing Deeps (55.2, 41.9), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.\n\nFound commonly in small groups around the 3 main underground zones.",
        [4458] = "No implemented acquisition source is verified for this species. The old vendor/drop/wild-pet label is not a usable acquisition method.",
        [4460] = "Start wild pet battles in Hallowfall (48.7, 35.6) and look for Arathi Chicken in the opposing team's secondary slots. Reduce its health below 35%, trap it, and win the battle.\n\nFound around farms in Hallowfall, frontline & backline.",
        [4461] = "Start wild pet battles in Hallowfall (48.9, 40.0) and look for Greenlands Chicken in the opposing team's secondary slots. Reduce its health below 35%, trap it, and win the battle.\n\nLikely a Rare spawn of Arathi Chicken, can be found frontline & backline. Coords are some confirmed repeat spawn spots.",
        [4462] = "Complete Tale of Tails from Attica Whiskervale in Hallowfall (64.5, 18.8) to receive Thunder.\n\nObjectives: - Lynx kitten Beef - Lynx kitten Beans - Lynx kitten Thunder - Lynx kitten Cap'n Elaena - Attica's Cave Torch\n\nRequires Renown 3 with Hallowfall Arathi.",
        [4463] = "Buy Tiberius from Auralia Steelstrike in Hallowfall (41.3, 53.1) for 6,500 Resonance Crystals.\n\nRequires Renown 15 with Hallowfall Arathi.",
        [4464] = "Buy Bean from Pelefien in City of Threads (Umbral Bazaar) (50.5, 26.3) for 2,250 Kej.",
        [4465] = "Complete Save Tomothy from Miral Murder-Mittens in Hallowfall (60.3, 21.2) to receive Vanilla.\n\nObjectives: - The Grasping Darkness",
        [4467] = "Loot Hallowfall Sparkfly in Hallowfall (66.8, 25.3) to obtain Hallowed Glowfly.\n\nRequires level 80. Use a light source item then walk along the river near Stillstone Pond. With time Sparkbugs will appear next to you and randomly may be interactable, granting the pet.\n\nRequires Renown 3 with Hallowfall Arathi.",
        [4469] = "Defeat Goldie Baronbottom in Isle of Dorn (76.6, 43.8) and loot Bop. This is a chance drop.",
        [4470] = "Loot Scary Dark Chest in The Ringing Deeps (54.7, 30.3) to obtain Oop'lajax.\n\nLit up all candles.",
        [4471] = "Find a wild Aubergine Scootlefish in Azj-Kahet (37.4, 54.2), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4472] = "Defeat Shadowrooted Vine in Hallowfall (65.4, 32.2) and loot Shadowbog Hopper. This is a chance drop.\n\nSeems to only come from vines in Stillstone Pond\n\nRequires Renown 3 with Hallowfall Arathi.",
        [4473] = "Loot Trapped Trove in City of Threads (Umbral Bazaar) (67.4, 74.4) to obtain Spinner.\n\nIT'S A TRAP! Navigate through the web traps to get to the treasure.",
        [4476] = "Buy Itchbite from Clutchmother Marn'tiq in City of Threads (Umbral Bazaar) (44.2, 17.1) for 2,250 Kej.",
        [4477] = "Find a wild Verdant Scootlefish in Azj-Kahet (38.5, 56.1), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4478] = "No implemented acquisition source is verified for this species. The old vendor/drop/wild-pet label is not a usable acquisition method.",
        [4480] = "Find a wild Shadowy Oozeling in Azj-Kahet (63.6, 85.1), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.\n\nInteract with Black Blood Extractor objects in area until you reach at least 10x Unseeming Shift debuff to see this pet.",
        [4481] = "Start wild pet battles in Azj-Kahet (61.0, 74.8) and look for Voidling Ooze in the opposing team's secondary slots. Reduce its health below 35%, trap it, and win the battle.\n\nInteract with Black Blood Extractor objects in area until you reach at least 10x Unseeming Shift debuff to see this pet. Can also be found as a backline pet around the zone.",
        [4482] = "Learn Khaz Algar Alchemy and unlock Thaumaturgy. Perform Thaumaturgy on eligible stacks of materials; Writhing Transmutagen is a rare bonus discovery from the process, rather than a directly craftable pet recipe. Repeat conversions if you want to obtain it yourself, or buy the learned pet in a cage from another player. No particular number of conversions guarantees the pet.",
        [4483] = "Start wild pet battles in Azj-Kahet (57.3, 63.7) and look for Vile Bloodtick in the opposing team's secondary slots. Reduce its health below 35%, trap it, and win the battle.\n\nIt can be found both as a frontline and a backline pet in battles throughout Azj-Kahet.",
        [4484] = "Find a wild Frenzied Bloodtick in The Ringing Deeps (68.1, 90.8), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4485] = "Find a wild Mossy Snail in Isle of Dorn (63.6, 57.4), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4488] = "This species is an opposing battle pet, not a collectible companion. The marker locates its trainer or boss encounter; the pet cannot be captured or learned.",
        [4489] = "Complete a War Within delve and open the Heavy Trunks in the treasure room after the final objective. Bouncer is a random chest reward; Kobyss-themed delves such as The Sinkhole and Tak-Rethan Abyss are its themed sources. Loot the ordinary completion chests as well as any eligible bountiful chest. Learn the pet from the item if it drops, or buy a caged Bouncer from another player.",
        [4490] = "Earn Family Battler of Khaz Algar: 10 Points Account-wide progress Complete the following achievements. - Aquatic Battler of Khaz Algar - Critter Battler of Khaz Algar - Elemental Battler of Khaz Algar - Humanoid Battler of Khaz Algar - Mechanical Battler of Khaz Algar - Beast Battler of Khaz Algar - Dragonkin Battler of Khaz Algar - Flying Battler of Khaz Algar - Magic Battler of Khaz Algar - Undead Battler of Khaz Algar",
        [4491] = "Buy Jump Jump from Lady Vinazian in Azj-Kahet (55.3, 41.2) for 2,250 Kej.\n\nRequires Renown 15 with Severed Threads.",
        [4492] = "Buy Fringe from Clutchmother Marn'tiq in City of Threads (Umbral Bazaar) (44.2, 17.1) for 2,250 Kej.",
        [4495] = "Buy Skippy from Erani in Dornogal (58.5, 64.9) for 50 Polished Pet Charm.",
        [4496] = "Finish War Within delves and loot the Heavy Trunks in the final treasure room for a chance at Wriggle. Its themed sources are nerubian delves, including Earthcrawl Mines and Skittering Breach. A random pet drop is not guaranteed by completing the delve. Learn the dropped item, or obtain a caged Wriggle from the Auction House.",
        [4498] = "Find a wild Ebon Ploughworm in The Ringing Deeps (39.2, 27.6), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4499] = "Find a wild Common Ploughworm in The Ringing Deeps (36.4, 27.9), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4500] = "Earn Worm Theory: 10 Points Account-wide progress Complete the following quests in Rak-Ush and the Wormlands. - Grub Run - Worm Sign, Sealed, Delivered - Wormcraft Rumble",
        [4502] = "No implemented acquisition source is verified for this species. The old vendor/drop/wild-pet label is not a usable acquisition method.",
        [4506] = "Finish Fungal Folly on the Isle of Dorn or Mycomancer Cavern in Hallowfall, then open the Heavy Trunks in the final treasure room for a chance at Violet Sporbit. It has also been reported from other delve completion chests, including ordinary low-tier runs; it does not require capturing a wild pet. Learn the dropped item or purchase a caged Violet Sporbit from another player.",
