        [4570] = "Complete Home Is Where the Candle Is from Skitter in The Ringing Deeps (42.9, 33.3) to receive Cinderwold Sizzlestinger.\n\nAssist Fourman Grimes, Janky, and Granny Scribbles.",
        [4571] = "Find a wild Pinkskin Burrower in The Ringing Deeps (43.6, 31.6), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4573] = "Find a wild Skittish Sniffler in The Ringing Deeps (52.6, 43.8), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4574] = "Find a wild Snuffling in The Ringing Deeps (60.5, 48.5), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.\n\nFound around the area of Taelloch/Obsidian Hollow.",
        [4575] = "Complete a kobold-themed War Within delve, such as The Waterworks or The Dread Pit, and loot the Heavy Trunks after the final objective. Sneef is a chance reward from the completion treasure room; it can also appear in other delve completion chests. Learn the pet from its item, or buy a caged Sneef on the Auction House.",
        [4576] = "Buy Guacamole from Waxmonger Squick in The Ringing Deeps (43.1, 32.9) for 6,500 Resonance Crystals.\n\nRequires Renown 17 with Assembly of the Deeps.",
        [4577] = "Find a wild Cinderhoney Emberstinger in Isle of Dorn (74.0, 40.1), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4579] = "Buy Muskpaw Calf from Nostwin in Timeless Isle (42.7, 56.6).\n\nPandaria Remix has ended. This achievement pet cannot be caged or traded.",
        [4580] = "Buy Astral Emperor's Serpentling from Nostwin in Timeless Isle (42.7, 56.6).\n\nPandaria Remix has ended. This achievement pet cannot be caged or traded.",
        [4581] = "Earn A Champion's Tour: The War Within: 20 Points Account-wide progress Complete each of the following World PvP World Quests in the War Within 5 times. - Elemental Excavation - Digging into Trouble - Fending off Darkness - Polarized - Along for the Ride - Foggy Faceoff - Bells of the Light - Serving the Queen",
        [4582] = "Complete Permanent Hire from Kish'nal in Azj-Kahet (75.0, 80.7) to receive Rak-Ush Battleshell.\n\nObjectives: - Speak to Saffrin",
        [4586] = "Buy Brown Leafbug from Erani in Dornogal (58.5, 64.9) for 50 Polished Pet Charm.",
        [4594] = "Loot Turtle's Thanks in Dornogal (58.3, 30.3) to obtain Dalaran Sewer Turtle.",
        [4596] = "First befriend Dog at the Heartland in Valley of the Four Winds by completing Lost and Lonely, then build the Herb Garden in your Warlords garrison so Dog moves in. Find a Loose Pebble on the streets of Legion Dalaran and show it to Dog in your garrison so he moves to Dalaran. On the Isle of Dorn, inspect the Half-Buried Dog Bowl at (31.4, 51.3) near Dalaran's crash site, then interact with Dog there and pet his head to learn Faithful Dog. The source notes follow your first unfinished step, so an established friendship does not need to be repeated.",
        [4597] = "Buy Wobbles from Gnawbles in The Ringing Deeps (43.5, 35.3) for 1 Firelight Ruby.",
        [4598] = "Buy Coppers from Gnawbles in The Ringing Deeps (43.5, 35.3) for 1 Firelight Ruby.",
        [4599] = "Loot Memory Cache in City of Threads (62.7, 87.9) to obtain Mind Slurp.\n\nInteract with Black Blood Extractors in area or stand in Black Blood pools until you reach at least 50 Unseeming Shift debuff to see Corrupted Memory near the cache. Kill it to obtain key for cache.",
        [4628] = "Find a wild Tidal Kroling in Siren Isle, start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4631] = "Earn Family Battler of Undermine: 10 Points Account-wide progress Complete the following achievements. - Aquatic Battler of Undermine - Critter Battler of Undermine - Elemental Battler of Undermine - Humanoid Battler of Undermine - Mechanical Battler of Undermine - Beast Battler of Undermine - Dragonkin Battler of Undermine - Flying Battler of Undermine - Magic Battler of Undermine - Undead Battler of Undermine",
        [4632] = "Buy Eepy from Lab Assistant Laszly in Undermine (27.5, 72.8) for 6,500 Resonance Crystals.\n\nRequires Revered with Steamwheedle Cartel.",
        [4636] = "In Undermine, unlock the G-99 Breakneck and use its job interface to complete Shipping and Handling streaks. Renown 8 unlocks Expert Haggler rewards; complete nine consecutive jobs for a chance at cosmetic rewards. There is no stationary pet drop NPC.",
        [4637] = "Buy Wavebreaker Mechasaur from Boatswain Hardee in Undermine (63.4, 16.7) for 6,500 Resonance Crystals.\n\nRequires Revered with Blackwater Cartel.",
        [4638] = "Buy Crimson Mechasaur from Ditty Fuzeboy in Undermine (35.4, 41.4) for 10 Miscellaneous Mechanica.",
        [4639] = "Open Sifted Pile of Scrap in Undermine (25.8, 38.1) for a chance at Viridian Mechasaur. Obtain the container with 333 Empty Kaja'Cola Can.\n\nFrequently around the zone a pile of scrap will be marked on the map, ready for excavation. Once started, there is a two minute timer to dig up as much as possible, clearing obstacles and dodging projectiles. Renown unlocks new drops and efficiency upgrades, and a rare mob can sometimes spawn at max excavation progress.",
        [4640] = "Buy Fun-Size Flarendo from Snix Longpocket in Undermine (42.0, 50.2).\n\nRequires Renown 9 with Gallagio Loyalty Rewards Club.",
        [4641] = "Buy Rocketfist from Shredz the Scrapper in Undermine (53.3, 72.7) for 6,500 Resonance Crystals.\n\nRequires Revered with Venture Company.",
        [4642] = "Complete Inoperative Mega-Mecha Gorilla in Undermine to receive Mega-Mecha Gorilla.\n\nTake the Inoperative Mega-Mecha Gorilla to Ditty Fuzeboy for repairs.",
        [4643] = "Buy Tiny Torq from Skitto Screwjack in Undermine (42.0, 50.2).\n\nRequires Renown 9 with Gallagio Loyalty Rewards Club.",
        [4644] = "Buy Professor Punch from Ditty Fuzeboy in Undermine (35.4, 41.4) for 8 Miscellaneous Mechanica.",
        [4645] = "Buy Bilgewater Junkhauler from Rocco Razzboom in Undermine (39.2, 22.2) for 6,500 Resonance Crystals.\n\nRequires Revered with Bilgewater Cartel.",
        [4646] = "In Undermine, unlock the G-99 Breakneck and use its job interface to complete Shipping and Handling streaks. Renown 8 unlocks Expert Haggler rewards; complete nine consecutive jobs for a chance at cosmetic rewards. There is no stationary pet drop NPC.",
        [4647] = "Complete a goblin-themed War Within delve, such as Excavation Site 9 or Sidestreet Sluice, and open the Heavy Trunks in the final treasure room for a chance at Mr. DELVER. Drops have also been reported from other delve completion chests. Learn the pet from the item, or buy a caged copy from the Auction House; defeating the friendly Mr. DELVER encounter character is not required.",
        [4648] = "Buy Steamwheedle Flunkie from Ditty Fuzeboy in Undermine (35.4, 41.4) for 5 Miscellaneous Mechanica.",
        [4649] = "Buy Blackwater Kegmover from Ditty Fuzeboy in Undermine (35.4, 41.4) for 5 Miscellaneous Mechanica.",
        [4650] = "Buy Venture Companyman from Ditty Fuzeboy in Undermine (35.4, 41.4) for 5 Miscellaneous Mechanica.",
        [4651] = "Find a wild Wily Rat in Undermine (40.4, 47.6), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4652] = "Find a wild Acid-Drenched Rat in Undermine (33.1, 66.4), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4653] = "Buy Lab Rat from Angelo Rustbin in Undermine (25.8, 38.1) for 3 Vintage Kaja'Cola Can.\n\nFrequently around the zone a pile of scrap will be marked on the map, ready for excavation. Once started, there is a two minute timer to dig up as much as possible, clearing obstacles and dodging projectiles. Renown unlocks new drops and efficiency upgrades, and a rare mob can sometimes spawn at max excavation progress.",
        [4654] = "Find a wild Underroach in Undermine (28.0, 64.3), start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4655] = "Buy Cruncher from Angelo Rustbin in Undermine (25.8, 38.1) for 1 Vintage Kaja'Cola Can.\n\nFrequently around the zone a pile of scrap will be marked on the map, ready for excavation. Once started, there is a two minute timer to dig up as much as possible, clearing obstacles and dodging projectiles. Renown unlocks new drops and efficiency upgrades, and a rare mob can sometimes spawn at max excavation progress.",
