        [4731] = "Find a wild Storm-Infused Snapdragon in Siren Isle, start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
        [4732] = "Find a wild Scavenging Snapdragon in Siren Isle, start a pet battle, reduce its health below 35%, and use your trap. Win the battle to keep the captured pet.",
