    toys = {
        [131717] = "Complete A Beacon of Hope from Tae'thelan Bloodwatcher in Azsuna (47.4, 42.6) to receive Starlight Beacon.\n\nObjectives: - Ancient Highborne Artifact",
        [138111] = "Complete Stormforged Grapple Launcher from Stormforged Grapple Launcher in Stormheim (33.8, 45.7) to receive Stormforged Grapple Launcher.\n\nThis looks like one of the grapple launchers the local vrykul use to scale the steep ridges in Stormheim. This could come in handy.",
        [141605] = "Complete Uniting the Isles from Archmage Khadgar in Dalaran (Broken Isles) to receive Flight Master's Whistle.\n\nObjectives: - The Nightfallen: - Court of Farondis: - Highmountain Tribe: - Dreamweavers: - Valarjar:",
        [167698] = "Buy Secret Fish Goggles from Danielle Anglers in Mechagon (37.2, 47.2).\n\nThis is a toy since 11.1.5. If you buy the goggles from the vendor, the toy is automatically added to your Toy Box. You do not have to click it on to add it (as you do with most toys). But, the vendor won't sell you the goggles if you already have one on your bag or your bank, so make sure to delete it first.",
        [170197] = "Purchase for 500 Plunder in the Plunderstore when Plunderstorm is available. This uses the event shop interface, not a fixed NPC in the normal world.",
        [197961] = "Earn Daycare Derby: 10 Points Account-wide progress Participate in every Little Scales Daycare Whelp Race. - Runaway Rusziona - Zhoomsa - Blistering Belastrasza - Zaleth on the Go - Pole Position Posidriss",
        [204220] = "Complete Hraxian's Unbreakable Will from Veritistrasz in Zaralek Cavern (40.2, 68.4) to receive Hraxian's Unbreakable Will.\n\nObjectives: - Dusty Vase",
        [204686] = "Complete A Sliver of Silver from Watcher Koranos in Tirisfal Glades (42.1, 85.7) to receive Titan Containment Device.\n\nObjectives: - Use the Titan Transporter to return to Tyrhold. - Return to the Aspects - Silver Scale activated - Tyr Moved\n\nRequires Renown 12 with Valdrakken Accord.",
        [204818] = "Obtain the finished Mallard Mortar from a player who crafts it with Engineering. Search the Auction House for the exact toy name, buy it and use the item to add it to the Toy Box. You can also request a craft from a player who knows this recipe; learning the toy does not require taking the crafting profession yourself.",
        [205045] = "Obtain the finished B.B.F. Fist from a player who crafts it with Jewelcrafting. Search the Auction House for the exact toy name, buy it and use the item to add it to the Toy Box. You can also request a craft from a player who knows this recipe; learning the toy does not require taking the crafting profession yourself.",
        [205419] = "Defeat Dinn in Zaralek Cavern (29.2, 50.7) and loot Dinn's Drum. This is a chance drop.",
        [205463] = "Defeat Moltenbinder's Disciple in Emerald Dream (45.8, 18.8) and loot Molten Lava Ball. This is a chance drop.",
        [205796] = "Defeat Invoq in Zaralek Cavern (46.0, 33.3) and loot Molten Lava Pack. This is a chance drop.",
        [205908] = "Complete A Peaceful Farewell from Senegos in The Azure Span (39.3, 63.6) to receive Inherited Wisdom of Senegos.\n\nObjectives: - Speak with Senegos one last time\n\nYou will find this in your mailbox upon completing this quest",
        [205936] = "Buy New Niffen No-Sniffin' Tonic from Lyssa in Zaralek Cavern (56.8, 56.4).",
        [205963] = "Buy Sniffin' Salts from Harlowe Marl in Zaralek Cavern (56.5, 55.6) for 200 Dragon Isles Supplies.\n\nRequires Renown 11 with Loamm Niffen.",
        [206008] = "Defeat Treasure Goblin in Durotar (44.1, 19.3) and loot Nightmare Banner. This is a chance drop.\n\nEvery 60 Minutes a Portal spawns in Dornogal, Stormwind and Orgrimmar, causing a Treasure Goblin to appear after 5 minutes. Can also spawn in Undermine after defeating a rare.",
        [206195] = "Buy Path of the Naaru from Gaal in Krokuun (56.7, 68.6) for 900 Veiled Argunite and 90 Empyrium and 90 Lightweave Cloth.",
        [206267] = "Earn Legend: Dragonflight Season 2: Win 100 Rated Solo Shuffle rounds while at Elite rank during Dragonflight Season 2. - Win 100 Rated Solo Shuffle rounds while at Elite rank during Dragonflight Season 2.\n\nThe original Dragonflight Solo Shuffle season has ended. Its Legend pennant reward can no longer be earned.",
        [206343] = "Earn Legend: Dragonflight Season 1: Win 100 Rated Solo Shuffle rounds while at Elite rank during Dragonflight Season 1. - Win 100 Rated Solo Shuffle rounds while at Elite rank during Dragonflight Season 1.\n\nThe original Dragonflight Solo Shuffle season has ended. Its Legend pennant reward can no longer be earned.",
        [206565] = "Unlock the restored Scholomance and Wards of the Dread Citadel route into old Naxxramas. Inside Naxxramas, repair the Makeshift Grappling Hook and use it to reach Zackett Skullsmash above Thaddius's room. Bring Black Coffee to wake him and complete his introduction. Exchange Scourgestones for Death's Bargaining Chips, then buy Plagued Grain from Zackett for 15 chips. The Eastern Plaguelands map marker is the Naxxramas entrance, not an outdoor location for the vendor. Zackett is a merchant; do not attack him for this toy.",
        [206696] = "Complete Unfinished Thinking Cap in Valdrakken (26.6, 53.9) to receive Tricked-Out Thinking Cap.\n\nTake the Unfinished Thinking Cap to Fangli Hoot in Valdrakken.",
        [206993] = "Defeat Temporal Investi-gator in Thaldraszus (52.3, 81.4) and loot Investi-gator's Pocketwatch. This is a chance drop.\n\nGo in Everywhere Inn at 2nd floor, borrow Melly's Metronographer, use it near Bartender Bob, buy Infinitea from Bartender Blob and fly at coords, use it and interact with object to summon rare",
        [207092] = "Buy the finished Portable Party Platter on the Auction House or have an engineer craft it. To learn the schematic yourself, reach Dragon Isles Engineering 50 and carry Light Parchment and Engineer's Ink. Stand near a mage who has a Chef's Splendid Rolling Pin equipped, knows a Dragon Isles dessert recipe, and gains the Well Fed buff by eating. The mage conjures a dessert and the nearby engineer receives the schematic. Learn it, craft the platter and use the finished item to add it to your Toy Box.",
        [207099] = "Earn Many Boxes, Many Rockses: 5 Points Account-wide progress Open 50 boxes of rocks, releasing the elementals within. - Opened Box of Rocks",
        [207730] = "Speak with Tithris in the Roasted Ram. Bring the Torch of Pyrreth and follow the brazier clues to Teerakai.",
        [208092] = "Complete Artifact Secured in The Waking Shores (54.6, 20.4) to receive Torch of Pyrreth.\n\nReturn the Torch of Pyrreth to Preservationist Kathos in Valdrakken.",
        [208096] = "Loot Familiar Journal in Western Plaguelands (69.1, 73.0) to obtain Familiar Journal.\n\nWith 10.1.5, Blizzard readded the original version of Scholomance! Thank you, Blizzard! -Crieve Here is how to get started: 1. Obtain 'Krastinov's Bag of Horrors' from the rare spawn Doctor Theolen Krastinov in Scholomance, Heroic difficulty. This step can be skipped if you are accompanied by someone who already has the toy. 2. Defeat Darkmaster Gandling in Headmaster's Retreat and enter the upper level centre room. 3. Find a pile of bones on the ground in the southeastern part of the room, and use the toy 'Krastinov's Bag of Horrors'. 4. Eva Sarkhoff should now have spawned, but you cannot interact with her before you remove the toy visage/buff named 'Surgical Alterations'. 5. Accept Eva Sarkhoof's quest and her Inert Spectral Essence. Loot Eva's Femur from the pile of bones. 6. Walk back upstairs to The Viewing Room. There are two bookcases in the southwestern corner of the room. Eva's Journal can be found on a middle shelf on the backside of the left bookcase. 7. Obtain the reagents 3x Dark Runes and 5x Essence of Undeath and use the Inert Spectral Essence. Equip the crafted trinket 'Spectral Essence'. 8. Obtain candles from doing objectives around Caer Darrow (outside Scholomance): 8.1 Loot 'The Deed to Andorhal' from inside Andorhal Townhall at 43.35, 69.3, and give it to Magistrate Marduke at 70.5, 74.0. 8.2 Loot 'Bucket of Fountain Water' from the candlelit fountain at 68.9, 78.8, and give it to Joseph Dirte at 68.0, 74.8. 8.3 Loot 'Trampled Doll' from the meatwagon in Darrowshire at 35.7, 83.5. (Eastern Plaguelands!), return to Caer Darrow and give it to Sammy at 69.15, 78.7. 8.4 Loot 'The Road Ahead' from a wall inside old Corin's Crossing tavern at 55.0, 64.0. (Eastern Plaguelands!), return to Caer Darrow and give it to Artist Renfray at 65.8, 75.4. 8.5 Loot 'Undelivered Shipment of Smokes' from a wagon behind the fountain at King's Square in Stratholme, return to Caer Darrow and give it to Rory at 63.4, 75.5. 9. Use Eva's Journal to begin the ritual at 69.7, 71.7, inside Caer Darrow keep/open world Scholomance.\n\nThe Familiar Journal itself can be found in the Viewing Room of Old Scholomance, on the second bookshelf from the left wall, near the mini-boss Marduk Blackpool. All you have to do is pick up the book, and the toy is yours! It's as simple as that.",
        [208186] = "Earn Temporal Acquisitions Specialist: 15 Points Account-wide progress Find a variety of items while completing Time Rifts. - Titanic Disc - Azmerlothian Hourglass - Corrupted Ashbringer - Chipped Stone Tablet - Boffins - Blood Soaked Book - Gilded Vase - Antlered Skull - Mechanized Cog - Oil-Soaked Log Book - Map to Suramar - Watcher's Log - Amber Blade - A Fish",
        [208415] = "Complete Dawn of the Infinite: Chrono-Lord Deios from Chromie in Thaldraszus (62.2, 83.2) to receive Stasis Sand.",
        [208421] = "Earn Best Stellar: 5 Points Account-wide progress Read the entire Rituals of the New Moon series written by scribes. - Rituals of the New Moon - Black Wolf - Rituals of the New Moon - Red Wolf - Rituals of the New Moon - White Wolf - Rituals of the New Moon - Grey Wolf",
        [208433] = "Earn Dragonriding Challenge: Dragon Isles: Bronze: 20 Points Account-wide progress Obtain bronze for all Challenge races in the Dragon Isles. - Waking Shores Challenge: Bronze - Azure Span Challenge: Bronze - Forbidden Reach Challenge: Bronze - Ohn'ahran Plains Challenge: Bronze - Thaldraszus Challenge: Bronze - Zaralek Cavern Challenge: Bronze",
        [208658] = "Complete Proof and Promise from Hooded Saboteur in Krokuun (73.0, 32.3) to receive Mirror of Humility.\n\nObjectives: - Brilliant Star - Legion Teleporter located - Legion Teleporter used - Return to Velen",
        [208798] = "Complete Disc Delivery from Nozdormu in Thaldraszus (60.4, 58.7) to receive Recorded Memories of Tyr's Guard.\n\nObjectives: - Disc placed - Tyr Restored\n\nRequires Renown 12 with Valdrakken Accord.",
        [209858] = "Buy Dreamsurge Remnant from Celestine of the Harvest in The Waking Shores (58.4, 67.8) for 500 Dreamsurge Coalescence.",
        [209944] = "Buy Friendsurge Defenders from Celestine of the Harvest in The Waking Shores (58.4, 67.8) for 500 Dreamsurge Coalescence.",
        [210411] = "Loot Pineshrew Pile in Emerald Dream (37.3, 30.7) to obtain Fast Growing Seed.",
        [210455] = "Complete Our Path Forward from Grand Anchorite Almonen in The Exodar (64.4, 87.3) to receive Draenic Hologem.\n\nObjectives: - Ask Velen to begin the ceremony\n\nTo unlock this questline you need to be logged in on a level 50 Draenei.",
        [210725] = "Loot Hidden Moonkin Stash in Emerald Dream (47.5, 34.9) to obtain Owl Post.",
        [210864] = "Complete Sleepy Druid in Emerald Dream from Thaalean in Emerald Dream (58.1, 77.3) to receive Improvised Leafbed.\n\nObjectives: - Kill Credit: Lullaby Line 1 (Sleepy Druid) - Kill Credit: Lullaby Line 2 (Sleepy Druid) - Kill Credit: Lullaby Line 3 (Sleepy Druid) - Lullaby Sang to Thaalean",
        [211931] = "Buy Abyss Caller Horn from Reno Jackson in Dornogal (47.6, 45.0) for 5,000 Resonance Crystals.",
